import {esc} from './weather-tools.js';
import {weatherPatch} from './climate-engine.js';
import {paintEdition} from './studio-canvas.js';
const $=s=>document.querySelector(s);
export function createStudio(ctx){
 let tool='clip';let draft={title:'Il cielo fa notizia.',caption:'',label:'EDIZIONE DEL CIELO',template:'news',format:'square',hud:true,zoom:1,signature:false},media=[],index=0,stream=null,camera=null,frame=0,record=null,recordStream=null,timer=0,output=null,outputURL=null,outputName='',lastPaint=0,busy=false,revision=0,postId=crypto.randomUUID(),publishing=false;
 try{draft={...draft,...JSON.parse(localStorage.getItem('ms-studio-draft')||'{}')}}catch{}
 const persist=()=>{try{localStorage.setItem('ms-studio-draft',JSON.stringify(draft))}catch{}};
 const info=()=>({...ctx.get(),brand:ctx.get().me?.profile?.name||'La mia redazione'});
 function page(){return `<section class="studio-workspace"><div class="studio-heading"><div><span class="eyebrow">CREATOR STUDIO</span><h1>La tua edizione del cielo.</h1></div><a href="#community">Community →</a></div><div class="studio-mode-switch"><a href="#testimonianza">◎ Testimonianza adesso</a><button aria-current="page">✦ Storia creativa</button><a href="#clash">Meteo Clash →</a></div><div class="studio-layout"><section class="studio-stage"><div class="studio-preview"><canvas id="edition-canvas" aria-label="Anteprima della slide: ${esc(draft.title)}"></canvas></div><div class="studio-slidebar"><button id="studio-prev" aria-label="Slide precedente">←</button><span id="studio-slide-count"></span><button id="studio-next" aria-label="Slide successiva">→</button></div><p class="studio-status" id="studio-status" role="status">Le foto e i video restano nel browser finché scegli di pubblicare.</p><video id="studio-result" controls playsinline hidden></video><a id="studio-result-download" class="button" hidden>Scarica il video</a></section><section class="studio-controls"><div class="studio-tools-nav" aria-label="Strumenti dell’editor">${[['clip','Clip'],['text','Testo'],['weather','Meteo'],['style','Stile'],['brand','Firma']].map(([id,label])=>`<button data-studio-tool="${id}" aria-pressed="${id===tool}">${label}</button>`).join('')}</div><section class="studio-tool-group" data-studio-pane="clip" ${tool==='clip'?'':'hidden'}><h2>Il tuo contenuto</h2><label class="field">Foto o video · fino a 7 file<input id="studio-file" type="file" multiple accept="image/jpeg,image/png,image/webp,video/mp4,video/webm"></label><div class="studio-buttons"><button id="studio-camera">Apri fotocamera HUD</button><button id="studio-stop" hidden>Ferma fotocamera</button><button id="studio-remove">Rimuovi file</button></div><p>File fino a 25 MB. Il montaggio usa l’inizio dei video ed esporta senza audio. Per una testimonianza senza modifiche usa la modalità dedicata.</p></section><section class="studio-tool-group" data-studio-pane="text" ${tool==='text'?'':'hidden'}><h2>Il tuo titolo, la tua voce.</h2><label class="field">Titolo<input id="studio-title" maxlength="90" value="${esc(draft.title)}"></label><label class="field">Sottotitolo<textarea id="studio-caption" maxlength="140">${esc(draft.caption)}</textarea></label><button id="studio-patch">Usa il bollettino Patch Notes</button><button data-studio-ai>✦ Chiedi un titolo a Lente</button></section><section class="studio-tool-group" data-studio-pane="weather" ${tool==='weather'?'':'hidden'}><h2>Il meteo dentro la storia.</h2><label class="studio-check"><input id="studio-hud" type="checkbox" ${draft.hud?'checked':''}> HUD meteo creativo</label><p>Il riquadro aggiunge temperatura e stato del cielo dalla previsione scelta. La barra è decorativa: non misura salute o pericolo.</p><p>Fonte e orario restano visibili. Per foto d’archivio il meteo mostrato è quello della composizione, non della ripresa.</p></section><section class="studio-tool-group" data-studio-pane="style" ${tool==='style'?'':'hidden'}><h2>La tua firma visiva.</h2><label class="field">Formato<select id="studio-format"><option value="square" ${draft.format==='square'?'selected':''}>Post quadrato · 1:1</option><option value="portrait" ${draft.format==='portrait'?'selected':''}>Story / Reel · 9:16</option></select></label><label class="field">Stile<select id="studio-template">${[['news','Edizione · news'],['arcade','Caldo · arcade'],['rain','Pioggia · cinema']].map(([k,n])=>`<option value="${k}" ${draft.template===k?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">Ingrandimento immagine<input id="studio-zoom" type="range" min="1" max="2" step=".05" value="${draft.zoom}"></label></section><section class="studio-tool-group" data-studio-pane="brand" ${tool==='brand'?'':'hidden'}><h2>Firma la tua edizione.</h2><label class="studio-check"><input id="studio-signature" type="checkbox" ${draft.signature?'checked':''}> Firma della redazione</label><label class="studio-check"><input id="studio-orbit" type="checkbox" ${draft.orbit?'checked':''}> Firma Orbitale · asset sbloccabile</label><p>La firma identifica il tuo media brand. I badge creativi non sono verifiche dell’evento.</p><a href="#redazione">Nome, firma e asset sbloccati →</a></section><section class="studio-tool-group studio-export"><h2>Pronto da condividere.</h2><div class="studio-buttons"><button id="studio-png" class="button">Scarica slide PNG</button><button id="studio-record">Crea clip di 9 secondi</button><button id="studio-trailer">Monta il trailer · 3 s per file</button><button id="studio-publish">Pubblica questa slide</button></div><p>Guarda l’anteprima prima di pubblicare. Durante il montaggio mantieni aperta questa pagina.</p></section></section></div></section>`}
 function current(){return camera||media[index]?.element||null}
 function draw(progress=0){const c=$('#edition-canvas');if(!c)return;if(c.width!==1080)c.width=1080;const height=draft.format==='portrait'?1920:1080;if(c.height!==height)c.height=height;paintEdition(c,draft,info(),current(),progress);c.setAttribute('aria-label','Anteprima slide: '+draft.title+'. '+draft.caption);const count=$('#studio-slide-count');if(count)count.textContent=camera?'Fotocamera attiva':media.length?'File '+(index+1)+' di '+media.length:'Slide tipografica'}
 function status(t){if($('#studio-status'))$('#studio-status').textContent=t}
 function stopCamera(){stream?.getTracks().forEach(t=>t.stop());stream=null;camera?.pause();if(camera)camera.srcObject=null;camera=null;cancelAnimationFrame(frame);$('#studio-camera')?.removeAttribute('disabled');if($('#studio-stop'))$('#studio-stop').hidden=true}
 function animate(t=0){if(!camera&&!record)return;if(!lastPaint||t-lastPaint>=1000/24){draw(record?Math.min(1,(performance.now()-record.started)/record.duration):0);lastPaint=t}frame=requestAnimationFrame(animate)}
 async function startCamera(){if(busy||record)return;if(!navigator.mediaDevices?.getUserMedia)return status('Fotocamera non supportata. Puoi importare un file.');const token=++revision;$('#studio-camera').disabled=true;try{const s=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment',width:{ideal:1280},height:{ideal:720}},audio:false});if(token!==revision||ctx.get().route!=='studio'){s.getTracks().forEach(t=>t.stop());return}stopCamera();stream=s;camera=document.createElement('video');camera.muted=true;camera.playsInline=true;camera.srcObject=s;await camera.play();if(token!==revision||ctx.get().route!=='studio'){stopCamera();return}$('#studio-stop').hidden=false;$('#studio-camera').disabled=true;status('Fotocamera attiva, senza microfono. Non viene trasmesso un live.');animate()}catch{stopCamera();status('Fotocamera non disponibile o consenso negato. Puoi importare una foto.')}}
 function releaseMedia(){media.forEach(m=>{m.element.pause?.();m.element.removeAttribute?.('src');URL.revokeObjectURL(m.url)});media=[];index=0}
 async function importMedia(files){if(busy)return;stopCamera();const token=++revision;const selected=[...files].slice(0,7);if(!selected.length)return;if(selected.some(f=>f.size>25000000||!['image/jpeg','image/png','image/webp','video/mp4','video/webm'].includes(f.type)))return status('Scegli JPG, PNG, WebP, MP4 o WebM fino a 25 MB.');busy=true;status('Preparo i file…');const loaded=[];try{for(const file of selected){const url=URL.createObjectURL(file),video=file.type.startsWith('video/'),el=video?document.createElement('video'):new Image();loaded.push({element:el,url,video,name:file.name});if(video){el.muted=true;el.playsInline=true;el.preload='auto'}await new Promise((resolve,reject)=>{const timeout=setTimeout(()=>reject(Error('Il file non risponde.')),10000);const done=()=>{clearTimeout(timeout);resolve()};el.onerror=()=>{clearTimeout(timeout);reject(Error('Formato non leggibile: '+file.name))};if(video)el.onloadeddata=done;else el.onload=done;el.src=url});if(!video&&el.naturalWidth*el.naturalHeight>1920*1920){const reduced=document.createElement('canvas'),scale=Math.min(1,1920/Math.max(el.naturalWidth,el.naturalHeight));reduced.width=Math.round(el.naturalWidth*scale);reduced.height=Math.round(el.naturalHeight*scale);reduced.getContext('2d').drawImage(el,0,0,reduced.width,reduced.height);loaded[loaded.length-1].element=reduced;el.removeAttribute('src');URL.revokeObjectURL(url)}if(token!==revision)throw Error('Importazione annullata.')}releaseMedia();media=loaded;index=0;draw();status('File pronti. La clip esportata usa la parte iniziale del video, senza audio.')}catch(e){loaded.forEach(m=>{m.element.pause?.();URL.revokeObjectURL(m.url)});status(e.message)}finally{busy=false}}
 function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
 function png(){draw();$('#edition-canvas')?.toBlob(blob=>blob?download(blob,'meteosocial-slide-'+(index+1)+'.png'):status('Esportazione non riuscita.'),'image/png')}
 function endRecord(){if(record?.recorder.state==='recording')record.recorder.stop();clearInterval(timer);timer=0}
 async function makeVideo(trailer=false){if(record||busy)return;if(!window.MediaRecorder||!HTMLCanvasElement.prototype.captureStream)return status('Esportazione video non supportata qui. Usa PNG.');if(trailer&&!media.length)return status('Importa foto o video per montare il trailer.');if(trailer)stopCamera();const mime=['video/mp4','video/webm;codecs=vp8','video/webm'].find(t=>MediaRecorder.isTypeSupported(t));if(!mime)return status('Questo browser non offre un formato video esportabile.');const token=++revision;busy=true;const startIndex=index;try{if(trailer)index=0;draw();const canvas=$('#edition-canvas');recordStream=canvas.captureStream(24);const recorder=new MediaRecorder(recordStream,{mimeType:mime,videoBitsPerSecond:2500000}),chunks=[],duration=trailer?media.length*3000:9000;record={recorder,started:performance.now(),duration};recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onerror=()=>{if(record)record.failed=true;status('Registrazione interrotta.');endRecord()};recorder.onstop=()=>{const failed=record?.failed;recordStream?.getTracks().forEach(t=>t.stop());recordStream=null;media.forEach(m=>m.element.pause?.());record=null;busy=false;clearInterval(timer);cancelAnimationFrame(frame);index=startIndex;if(token!==revision||ctx.get().route!=='studio')return;if(failed||!chunks.some(c=>c.size)){status('Il video non è stato creato. Riprova o scarica PNG.');return}output=new Blob(chunks,{type:mime});if(outputURL)URL.revokeObjectURL(outputURL);outputURL=URL.createObjectURL(output);const v=$('#studio-result'),a=$('#studio-result-download');v.src=outputURL;v.hidden=false;a.href=outputURL;outputName='meteosocial-'+(trailer?'trailer':'clip')+'.'+(mime.startsWith('video/mp4')?'mp4':'webm');a.download=outputName;a.hidden=false;status('Video pronto. Guarda l’anteprima e scaricalo. Audio non incluso.');draw();if(camera)animate()};if(trailer)index=0;const el=current();if(el?.tagName==='VIDEO'){if(!camera)el.currentTime=0;await el.play()}if(token!==revision)throw Error('Registrazione annullata');recorder.start(500);record.started=performance.now();status('Montaggio in corso. Mantieni questa pagina aperta…');animate();timer=setInterval(()=>{if(!record)return;const elapsed=performance.now()-record.started;if(trailer){const next=Math.min(media.length-1,Math.floor(elapsed/3000));if(next!==index){current()?.pause?.();index=next;const m=current();if(m?.tagName==='VIDEO'){m.currentTime=0;m.play().catch(()=>{})}}}if(elapsed>=duration)endRecord()},100)}catch(e){endRecord();recordStream?.getTracks().forEach(t=>t.stop());record=null;busy=false;status('Esportazione non riuscita. Puoi scaricare una slide PNG.')}}
 function publish(){if(!ctx.get().me)return ctx.login();if(record||busy||publishing)return status('Attendi il termine del montaggio.');draw();const image=$('#edition-canvas').toDataURL('image/jpeg',.8),caption=draft.title+(draft.caption?'\n'+draft.caption:'');if(image.length>1900000)return status('Immagine troppo grande. Riduci il contenuto o scaricala.');ctx.modal('Pubblica l’edizione',`<img class="studio-confirm" src="${image}" alt="Anteprima della slide da pubblicare"><label class="field">Città<input id="studio-city" required maxlength="80" value="${esc(ctx.get().place.source==='gps'?'':ctx.get().place.name)}"></label><label class="studio-check"><input id="studio-consent" type="checkbox" required> Posso condividere questa immagine. Ho controllato persone e dati privati.</label><p>La slide sarà pubblica come Osservazione. La grafica non certifica l’evento.</p>`,async()=>{if(!$('#studio-consent').checked)throw Error('Conferma il diritto di pubblicare.');if(publishing)return false;publishing=true;try{await ctx.api('posts',{id:postId,text:caption,city:$('#studio-city').value,kind:'Osservazione',photo:image});postId=crypto.randomUUID();ctx.invalidate();location.hash='community';ctx.toast('Edizione pubblicata.')}finally{publishing=false}});$('#confirm-dialog').textContent='Pubblica'}
 function bind(){if(ctx.get().route!=='studio')return;draw();document.querySelectorAll('[data-studio-tool]').forEach(b=>b.onclick=()=>{tool=b.dataset.studioTool;document.querySelectorAll('[data-studio-tool]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelectorAll('[data-studio-pane]').forEach(x=>x.hidden=x.dataset.studioPane!==tool)});const fields={title:'input',caption:'input',template:'change',format:'change',zoom:'input',hud:'change',signature:'change'};for(const [field,event]of Object.entries(fields))$('#studio-'+field)?.addEventListener(event,e=>{draft[field]=['hud','signature'].includes(field)?e.target.checked:field==='zoom'?Number(e.target.value):e.target.value;persist();draw()});$('#studio-orbit').onchange=e=>{if(!ctx.get().hasOrbit){e.target.checked=false;return ctx.toast('Sblocca la Firma Orbitale nella Redazione.')}draft.orbit=e.target.checked;persist();draw()};$('#studio-file').onchange=e=>importMedia(e.target.files);$('#studio-camera').onclick=startCamera;$('#studio-stop').onclick=()=>{revision++;endRecord();stopCamera();draw();status('Fotocamera spenta.')};$('#studio-remove').onclick=()=>{if(busy)return;revision++;stopCamera();releaseMedia();draw()};for(const [id,delta]of [['prev',-1],['next',1]])$('#studio-'+id).onclick=()=>{if(busy||!media.length)return;current()?.pause?.();index=(index+delta+media.length)%media.length;draw()};$('#studio-png').onclick=png;$('#studio-record').onclick=()=>makeVideo();$('#studio-trailer').onclick=()=>makeVideo(true);$('#studio-publish').onclick=publish;$('#studio-patch').onclick=()=>{const p=weatherPatch(ctx.get().weather,ctx.get().place.name);draft.title=p.title;draft.caption=p.lines.slice(0,2).join(' ').slice(0,140);$('#studio-title').value=draft.title;$('#studio-caption').value=draft.caption;persist();draw()};$('[data-studio-ai]').onclick=()=>ctx.askAI('Proponi un titolo editoriale breve sul meteo di '+ctx.get().place.name+'. Non inventare allerte o notizie.');if(outputURL){$('#studio-result').src=outputURL;$('#studio-result').hidden=false;$('#studio-result-download').href=outputURL;$('#studio-result-download').download=outputName;$('#studio-result-download').hidden=false}}
 document.addEventListener('visibilitychange',()=>{if(document.hidden){revision++;endRecord();stopCamera();status('Fotocamera e registrazione fermate perché l’app è in background.')}});
 return {page,bind,refresh(){if(ctx.get().route==='studio'&&!record)draw()},dispose(next){if(next==='studio')return;revision++;endRecord();stopCamera();media.forEach(m=>m.element.pause?.())}};
}
